  ('33040000-0000-4000-8000-000000000010', '32000000-0000-4000-8000-000000000004', 10,
   'What is lacking in the closed type of vascular bundles of monocot stem?',
   'xylem vessels do not have perforations', 'xylem is not surrounded by bundle sheath cells', 'Phloem lacks companion cells', 'cambium', 'D', 4, 1),
  ('33040000-0000-4000-8000-000000000011', '32000000-0000-4000-8000-000000000004', 11,
